#!/usr/bin/env python3
# Apply workflow-proposed translation corrections to Localizable.xcstrings,
# with a placeholder-safety guard: a correction is REJECTED if it changes the
# set/count of format placeholders relative to the source key (which would
# break runtime string formatting).
import json, re, collections, sys

CAT = 'SwiftMandarin/Localizable.xcstrings'
corr = json.load(open('/tmp/corrections.json'))

TOKEN = re.compile(r'%\d+\$@|%\d+\$lld|%@|%lld|%%|\$\{[^}]+\}')
def norm_tokens(v):
    if not v: return collections.Counter()
    t = [re.sub(r'%\d+\$', '%', x) for x in TOKEN.findall(v)]
    c = collections.Counter(t)
    c['\\n'] = (v.count('\n'))
    return c

d = json.load(open(CAT), object_pairs_hook=collections.OrderedDict)
s = d['strings']

applied, rejected, skipped = [], [], []
# Dedupe: last correction per (key,lang) wins, but prefer error>warning>nit
order = {'error':0,'warning':1,'nit':2}
best = {}
for c in corr:
    k=(c['key'], c['lang'])
    if k not in best or order.get(c.get('severity','nit'),3) < order.get(best[k].get('severity','nit'),3):
        best[k]=c

for (key, lang), c in best.items():
    sev = c.get('severity','nit')
    suggested = c['suggested']
    entry = s.get(key)
    if entry is None:
        rejected.append((key,lang,'key not found',c.get('reason',''))); continue
    locs = entry.setdefault('localizations', collections.OrderedDict())
    cur = locs.get(lang,{}).get('stringUnit',{}).get('value')
    # Placeholder safety: compare against the source key's tokens.
    src_tokens = norm_tokens(key)
    if norm_tokens(suggested) != src_tokens:
        rejected.append((key,lang,f'placeholder mismatch (src={dict(src_tokens)} vs sug={dict(norm_tokens(suggested))})', suggested)); continue
    if suggested == cur:
        skipped.append((key,lang,'no change')); continue
    if sev == 'nit':
        skipped.append((key,lang,f'nit (not auto-applied): {cur!r}->{suggested!r}')); continue
    locs.setdefault(lang, collections.OrderedDict())['stringUnit'] = collections.OrderedDict(
        [('state','translated'),('value',suggested)])
    applied.append((key,lang,cur,suggested,sev,c.get('reason','')))

# canonical nested order
def canon(entry):
    out=collections.OrderedDict()
    for ek in sorted(entry.keys()):
        val=entry[ek]
        if ek=='localizations':
            locs=collections.OrderedDict()
            for lk in sorted(val.keys()):
                su=val[lk].get('stringUnit')
                if su is not None:
                    val[lk]['stringUnit']=collections.OrderedDict([('state',su['state']),('value',su['value'])])
                locs[lk]=collections.OrderedDict(sorted(val[lk].items()))
            out[ek]=locs
        else:
            out[ek]=val
    return out
for key in list(s.keys()):
    s[key]=canon(s[key])

with open(CAT,'w') as f:
    json.dump(d,f,ensure_ascii=False,indent=2,separators=(',',' : ')); f.write('\n')
json.load(open(CAT))

print(f'APPLIED {len(applied)}:')
for key,lang,cur,sug,sev,reason in applied:
    print(f'  [{sev}] {lang} {key!r}: {cur!r} -> {sug!r}  ({reason})')
print(f'\nREJECTED {len(rejected)} (placeholder/other):')
for r in rejected: print('  ', r)
print(f'\nSKIPPED {len(skipped)} (nits/no-op):')
for sk in skipped[:60]: print('  ', sk)

